operations.reducer:
const { name, description, geography, currency, horizonYears } = action.input;
if (horizonYears != null && horizonYears < 1)
  throw new InvalidHorizonError("The horizon is at least one year");
const changesFigures =
  (currency !== undefined && currency !== state.currency) ||
  (horizonYears !== undefined && horizonYears !== state.horizonYears);
if (changesFigures && state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
if (name !== undefined) state.name = name ?? null;
if (description !== undefined) state.description = description ?? null;
if (geography !== undefined) state.geography = geography ?? null;
if (currency !== undefined) state.currency = currency ?? null;
if (horizonYears !== undefined) state.horizonYears = horizonYears ?? null;

operations.schema:
input AddSegmentInput {
  id: OID!
  name: String!
  description: String
}

operations.reducer:
if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const { id, description } = action.input;
const name = action.input.name.trim();
if (name === "") throw new SegmentNameRequiredError("A segment needs a name");
if (state.segments.some((s) => s.id === id))
  throw new DuplicateSegmentIdError(`Segment ${id} already exists`);
state.segments.push({
  id,
  name,
  description: description ?? null,
  accounts: null,
  accountsSource: null,
  annualValue: null,
  annualValueSource: null,
  serviceable: false,
  targetAccounts: null,
  organisationIds: [],
});

if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const { id, name, description, accounts, annualValue, serviceable, targetAccounts } = action.input;
const segment = state.segments.find((s) => s.id === id);
if (!segment) throw new SegmentNotFoundError(`Segment ${id} not found`);
if (name !== undefined && (name === null || name.trim() === ""))
  throw new SegmentNameRequiredError("A segment needs a name");
if ([accounts, annualValue, targetAccounts].some((n) => n != null && n < 0))
  throw new NegativeNumberError("A segment's numbers can't be negative");
const nextAccounts = accounts === undefined ? segment.accounts : accounts;
const nextTarget = targetAccounts === undefined ? segment.targetAccounts : targetAccounts;
if (nextAccounts != null && nextTarget != null && nextTarget > nextAccounts)
  throw new TargetAboveAccountsError("The target can't be more than the organisations in the segment");
if (name != null) segment.name = name.trim();
if (description !== undefined) segment.description = description ?? null;
if (accounts !== undefined) segment.accounts = accounts ?? null;
if (annualValue !== undefined) segment.annualValue = annualValue ?? null;
if (serviceable != null) segment.serviceable = serviceable;
if (targetAccounts !== undefined) segment.targetAccounts = targetAccounts ?? null;

if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const { id, figure, title, url, documentId } = action.input;
const segment = state.segments.find((s) => s.id === id);
if (!segment) throw new SegmentNotFoundError(`Segment ${id} not found`);
let source: typeof segment.accountsSource = null;
if (title != null || url != null || documentId != null) {
  if (title == null || title.trim() === "")
    throw new SourceTitleRequiredError("A source needs a title");
  if (url == null && documentId == null)
    throw new SourceLinkRequiredError("A source needs a link or a vault note");
  source = { title: title.trim(), url: url ?? null, documentId: documentId ?? null };
}
if (figure === "ACCOUNTS") segment.accountsSource = source;
else segment.annualValueSource = source;

operations.schema:
input LinkSegmentOrganisationInput {
  id: OID!
  organisationId: PHID!
}

operations.reducer:
const { id, organisationId } = action.input;
const segment = state.segments.find((s) => s.id === id);
if (!segment) throw new SegmentNotFoundError(`Segment ${id} not found`);
if (segment.organisationIds.includes(organisationId))
  throw new OrganisationAlreadyLinkedError("The organisation is already in the segment");
segment.organisationIds.push(organisationId);

operations.schema:
input UnlinkSegmentOrganisationInput {
  id: OID!
  organisationId: PHID!
}

operations.reducer:
const { id, organisationId } = action.input;
const segment = state.segments.find((s) => s.id === id);
if (!segment) throw new SegmentNotFoundError(`Segment ${id} not found`);
const index = segment.organisationIds.indexOf(organisationId);
if (index === -1)
  throw new OrganisationNotLinkedError("The organisation is not in the segment");
segment.organisationIds.splice(index, 1);

if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const index = state.segments.findIndex((s) => s.id === action.input.id);
if (index === -1) throw new SegmentNotFoundError(`Segment ${action.input.id} not found`);
state.segments.splice(index, 1);

if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const { id, amount, currency, year, sourceUrl, sourceDocumentId } = action.input;
const label = action.input.label.trim();
const sourceTitle = action.input.sourceTitle.trim();
if (label === "") throw new FigureLabelRequiredError("A figure needs to say what it measures");
if (amount < 0) throw new NegativeAmountError("A figure can't be negative");
if (sourceTitle === "") throw new SourceTitleRequiredError("A source needs a title");
if (sourceUrl == null && sourceDocumentId == null)
  throw new SourceLinkRequiredError("A source needs a link or a vault note");
if (state.publishedFigures.some((f) => f.id === id))
  throw new DuplicateFigureIdError(`Figure ${id} already exists`);
state.publishedFigures.push({
  id,
  label,
  amount,
  currency,
  year: year ?? null,
  source: { title: sourceTitle, url: sourceUrl ?? null, documentId: sourceDocumentId ?? null },
});

if (state.sizeStatus === "APPROVED")
  throw new FiguresApprovedError("Reopen the figures to change them");
const index = state.publishedFigures.findIndex((f) => f.id === action.input.id);
if (index === -1) throw new FigureNotFoundError(`Figure ${action.input.id} not found`);
state.publishedFigures.splice(index, 1);

const i = action.input;
const [xLabel, xLow, xHigh, yLabel, yLow, yHigh] = [i.xLabel, i.xLow, i.xHigh, i.yLabel, i.yLow, i.yHigh].map((t) => t.trim());
if ([xLabel, xLow, xHigh, yLabel, yLow, yHigh].some((t) => t === ""))
  throw new AxisTextRequiredError("Each axis needs a label and two ends");
state.axes = {
  x: { label: xLabel, low: xLow, high: xHigh },
  y: { label: yLabel, low: yLow, high: yHigh },
};

const { id, organisationId, x, y, note } = action.input;
if (!state.axes) throw new AxesRequiredError("Set the map's axes first");
if (x < 0 || x > 100 || y < 0 || y > 100)
  throw new PositionOutOfRangeError("A position runs from 0 to 100 on each axis");
if (state.players.some((p) => p.organisationId === organisationId))
  throw new OrganisationAlreadyPlacedError("The organisation is already on the map");
if (state.players.some((p) => p.id === id))
  throw new DuplicatePlayerIdError(`Player ${id} already exists`);
state.players.push({ id, organisationId, x, y, note: note ?? null, evidence: [] });

operations.schema:
input MovePlayerInput {
  id: OID!
  x: Float!
  y: Float!
}

operations.reducer:
const { id, x, y } = action.input;
const player = state.players.find((p) => p.id === id);
if (!player) throw new PlayerNotFoundError(`Player ${id} not found`);
if (x < 0 || x > 100 || y < 0 || y > 100)
  throw new PositionOutOfRangeError("A position runs from 0 to 100 on each axis");
player.x = x;
player.y = y;

operations.schema:
input SetPlayerNoteInput {
  id: OID!
  note: String
}

operations.reducer:
const player = state.players.find((p) => p.id === action.input.id);
if (!player) throw new PlayerNotFoundError(`Player ${action.input.id} not found`);
player.note = action.input.note ?? null;

operations.schema:
input LinkPlayerEvidenceInput {
  id: OID!
  refId: PHID!
  refTitle: String!
}

operations.reducer:
const { id, refId, refTitle } = action.input;
const player = state.players.find((p) => p.id === id);
if (!player) throw new PlayerNotFoundError(`Player ${id} not found`);
if (player.evidence.some((e) => e.id === refId))
  throw new EvidenceAlreadyLinkedError("The note is already linked");
player.evidence.push({ id: refId, title: refTitle });

operations.schema:
input UnlinkPlayerEvidenceInput {
  id: OID!
  refId: PHID!
}

operations.reducer:
const { id, refId } = action.input;
const player = state.players.find((p) => p.id === id);
if (!player) throw new PlayerNotFoundError(`Player ${id} not found`);
const index = player.evidence.findIndex((e) => e.id === refId);
if (index === -1) throw new EvidenceNotLinkedError("The note is not linked");
player.evidence.splice(index, 1);

const index = state.players.findIndex((p) => p.id === action.input.id);
if (index === -1) throw new PlayerNotFoundError(`Player ${action.input.id} not found`);
state.players.splice(index, 1);

operations.schema:
input SetOurPositionInput {
  x: Float!
  y: Float!
  note: String
  positioningId: OID
}

operations.reducer:
const { x, y, note, positioningId } = action.input;
if (!state.axes) throw new AxesRequiredError("Set the map's axes first");
if (x < 0 || x > 100 || y < 0 || y > 100)
  throw new PositionOutOfRangeError("A position runs from 0 to 100 on each axis");
state.us = { x, y, note: note ?? null, positioningId: positioningId ?? null };

operations.schema:
input ApproveSizeInput {
  approvedBy: EthereumAddress!
  approvedAt: DateTime!
}

operations.reducer:
const { approvedBy, approvedAt } = action.input;
if (state.sizeStatus !== "DRAFT")
  throw new SizeNotDraftError("Only draft figures can be approved");
const counted = state.segments.filter((s) => s.accounts != null && s.annualValue != null);
if (counted.length === 0)
  throw new NothingCountedError("Count at least one segment before approving");
const missing = counted.find((s) => !s.accountsSource || !s.annualValueSource);
if (missing)
  throw new SourceMissingError(`Add the sources for ${missing.name} before approving`);
state.sizeStatus = "APPROVED";
state.sizeApprovedBy = approvedBy;
state.sizeApprovedAt = approvedAt;

if (state.sizeStatus !== "APPROVED")
  throw new SizeNotApprovedError("Only approved figures can be reopened");
state.sizeStatus = "DRAFT";
state.sizeApprovedBy = null;
state.sizeApprovedAt = null;
